    private void assertWithinIssuingWindow(final String claim, final Duration offset) {
        final Optional<Long> value = inspector().payloadNumber(claim);
        assertTrue("expected a '" + claim + "' claim in " + inspector().payload(), value.isPresent());

        final long lower = this.issuedAtLowerBound.plus(offset).getEpochSecond();
        final long upper = this.issuedAtUpperBound.plus(offset).getEpochSecond();

        assertTrue("expected '" + claim + "' " + value.get() + " to fall within [" + lower + ", " + upper + "]",
                value.get() >= lower && value.get() <= upper);
    }

    private TestTokenInspector inspector() {
        assertNotNull("expected a token to be issued", this.issuedToken);

        return TestTokenInspector.of(this.issuedToken);
    }

    private String mint(final TokenSpec spec) {
        try {
            final TestTokenSigner signer = signerFor(spec);

            spec.keyId().ifPresent(signer::keyId);
            spec.issuer(this.configuration.issuer()).ifPresent(signer::issuer);

            return signer.subject(TEST_SUBJECT).issuedAt(Instant.now()).sign();
        } catch (final Exception e) {
            fail("failed to mint the token: " + e.getMessage());
            return null;
        }
    }

    private TestTokenSigner signerFor(final TokenSpec spec) {
        switch (spec.signatureKind()) {
        case NONE:
            return TestTokenSigner.unsigned();
        case HMAC:
            return TestTokenSigner.usingHmac(HMAC_SECRET);
        default:
            final String alias = spec.signerAlias().orElseThrow();
            final KeyPair keyPair = this.keyPairs.get(alias);
            assertNotNull("no key pair was created for alias '" + alias + "'", keyPair);

            return TestTokenSigner.using(keyPair.getPrivate());
        }
    }

    private String requirePreviouslyIssuedToken() {
        assertNotNull("this step requires a previously issued token", this.previouslyIssuedToken);

        return this.previouslyIssuedToken;
    }

    private String[] previouslyIssuedSegments() {
        return requirePreviouslyIssuedToken().split("\\.");
    }

    private void bindKeystore() {
        final Map<String, Object> properties = new HashMap<>();
        properties.put(ConfigurationService.KURA_SERVICE_PID, KEYSTORE_SERVICE_PID);

        this.jwtService.setKeystoreService(this.keystoreService, properties);
    }

    private void putPrivateKeyEntry(final String alias, final KeyPair keyPair, final Duration validFrom,
            final Duration validTo) {
        this.keyPairs.put(alias, keyPair);
        this.keystoreEntries.put(alias, new PrivateKeyEntry(keyPair.getPrivate(),
                new Certificate[] { certificate(alias, keyPair, validFrom, validTo) }));
    }

    private void putTrustedCertificate(final String alias, final KeyPair keyPair, final Duration validFrom,
            final Duration validTo) {
        this.keyPairs.put(alias, keyPair);
        this.keystoreEntries.put(alias,
                new TrustedCertificateEntry(certificate(alias, keyPair, validFrom, validTo)));
    }

    private static KeyPair rsaKeyPair(final String alias) {
        try {
            return TestCA.generateKeyPair();
        } catch (final Exception e) {
            fail("failed to create an RSA key pair for '" + alias + "': " + e.getMessage());
            return null;
        }
    }

    private static KeyPair ecKeyPair(final String alias) {
        try {
            final KeyPairGenerator generator = KeyPairGenerator.getInstance("EC");
            generator.initialize(256);

            return generator.generateKeyPair();
        } catch (final Exception e) {
            fail("failed to create an EC key pair for '" + alias + "': " + e.getMessage());
            return null;
        }
    }

    private static X509Certificate certificate(final String alias, final KeyPair keyPair, final Duration validFrom,
            final Duration validTo) {
        final Instant now = Instant.now();
        final boolean rsa = "RSA".equals(keyPair.getPrivate().getAlgorithm());

        try {
            return new TestCA(CertificateCreationOptions.builder(new X500Name("cn=" + alias + ", dn=kura.test")) //
                    .withSignatureAlgorithm(rsa ? "SHA256withRSA" : "SHA256withECDSA") //
                    .withStartDate(Date.from(now.plus(validFrom))) //
                    .withEndDate(Date.from(now.plus(validTo))) //
                    .build(), keyPair).getCertificate();
        } catch (final Exception e) {
            fail("failed to create a certificate for '" + alias + "': " + e.getMessage());
            return null;
        }
    }

    private static String wellFormedToken() {
        return base64Url("{\"alg\":\"RS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8)) + "."
                + base64Url("{\"iss\":\"kura\"}".getBytes(StandardCharsets.UTF_8)) + "."
                + base64Url("not-a-valid-signature".getBytes(StandardCharsets.UTF_8));
    }

    private static String base64Url(final byte[] bytes) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

